  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: GNM.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let SATELLITE_ID: VOffset = 4
    static let CONSTELLATION: VOffset = 6
    static let MESSAGE_TYPE: VOffset = 8
    static let TIME_SYSTEM: VOffset = 10
    static let TOC: VOffset = 12
    static let CLOCK_BIAS: VOffset = 14
    static let CLOCK_DRIFT: VOffset = 16
    static let CLOCK_DRIFT_RATE: VOffset = 18
    static let TRANSMISSION_TIME: VOffset = 20
    static let HEALTH: VOffset = 22
    static let HAS_HEALTH: VOffset = 24
    static let ACCURACY: VOffset = 26
    static let ACCURACY_INDEX: VOffset = 28
    static let HAS_ACCURACY_INDEX: VOffset = 30
    static let GROUP_DELAYS: VOffset = 32
    static let GROUP_DELAY_NAMES: VOffset = 34
    static let KEPLERIAN: VOffset = 36
    static let STATE: VOffset = 38
    static let DATA_SOURCES: VOffset = 40
  }

  ///  Satellite identifier as the source writes it, for example G05, E11, C21,
  ///  R24. Default empty.
  public var SATELLITE_ID: String? { let o = _accessor.offset(VT.SATELLITE_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var SATELLITE_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.SATELLITE_ID) }
  ///  Constellation of the satellite (the $GNO family's enumeration).
  public var CONSTELLATION: gnssConstellation { let o = _accessor.offset(VT.CONSTELLATION); return o == 0 ? .gps : gnssConstellation(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .gps }
  ///  Broadcast message the record came from. Default UNSPECIFIED.
  public var MESSAGE_TYPE: gnssNavMessageType { let o = _accessor.offset(VT.MESSAGE_TYPE); return o == 0 ? .unspecified : gnssNavMessageType(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unspecified }
  ///  System time scale TOC, TOE and the clock refer to, as the source names it.
  ///  Default empty.
  public var TIME_SYSTEM: String? { let o = _accessor.offset(VT.TIME_SYSTEM); return o == 0 ? nil : _accessor.string(at: o) }
  public var TIME_SYSTEMSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.TIME_SYSTEM) }
  ///  Time of clock, ISO 8601 on TIME_SYSTEM. Default empty.
  public var TOC: String? { let o = _accessor.offset(VT.TOC); return o == 0 ? nil : _accessor.string(at: o) }
  public var TOCSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.TOC) }
  ///  Satellite clock bias, s.
  public var CLOCK_BIAS: Double { let o = _accessor.offset(VT.CLOCK_BIAS); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Satellite clock drift, s/s.
  public var CLOCK_DRIFT: Double { let o = _accessor.offset(VT.CLOCK_DRIFT); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Satellite clock drift rate, s/s^2.
  public var CLOCK_DRIFT_RATE: Double { let o = _accessor.offset(VT.CLOCK_DRIFT_RATE); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Transmission time of the message, seconds of the system week.
  public var TRANSMISSION_TIME: Double { let o = _accessor.offset(VT.TRANSMISSION_TIME); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Health word as broadcast. Meaningful only when HAS_HEALTH.
  public var HEALTH: UInt32 { let o = _accessor.offset(VT.HEALTH); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  True when HEALTH carries a value (0 is a real health word); false (the
  ///  default) means absent.
  public var HAS_HEALTH: Bool { let o = _accessor.offset(VT.HAS_HEALTH); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  Signal accuracy (URA, SISA or URE index resolved), m.
  public var ACCURACY: Double { let o = _accessor.offset(VT.ACCURACY); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  The accuracy index as broadcast. Meaningful only when HAS_ACCURACY_INDEX.
  public var ACCURACY_INDEX: Int32 { let o = _accessor.offset(VT.ACCURACY_INDEX); return o == 0 ? 0 : _accessor.readBuffer(of: Int32.self, at: o) }
  ///  True when ACCURACY_INDEX carries a value (0 is a real index); false (the
  ///  default) means absent.
  public var HAS_ACCURACY_INDEX: Bool { let o = _accessor.offset(VT.HAS_ACCURACY_INDEX); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  Group delays (TGD, BGD, ISC), s, in the order of GROUP_DELAY_NAMES. Default
  ///  empty.
  public var GROUP_DELAYS: FlatbufferVector<Double> { return _accessor.vector(at: VT.GROUP_DELAYS, byteSize: 8) }
  public func withUnsafePointerToGroupDelays<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.GROUP_DELAYS, body: body) }
  ///  Names of the GROUP_DELAYS, same order and length. Default empty.
  public var GROUP_DELAY_NAMES: FlatbufferVector<String?> { return _accessor.vector(at: VT.GROUP_DELAY_NAMES, byteSize: 4) }
  ///  Keplerian parameters (GPS, Galileo, BeiDou, QZSS, NavIC).
  public var KEPLERIAN: gnssKeplerianBroadcast? { let o = _accessor.offset(VT.KEPLERIAN); return o == 0 ? nil : gnssKeplerianBroadcast(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  State vector (GLONASS, SBAS).
  public var STATE: gnssStateBroadcast? { let o = _accessor.offset(VT.STATE); return o == 0 ? nil : gnssStateBroadcast(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  The RINEX data-source bit field. Default 0.
  public var DATA_SOURCES: UInt32 { let o = _accessor.offset(VT.DATA_SOURCES); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  public static func startGNM(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 19) }
  public static func add(SATELLITE_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SATELLITE_ID, at: VT.SATELLITE_ID) }
  public static func add(CONSTELLATION: gnssConstellation, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CONSTELLATION.rawValue, def: 0, at: VT.CONSTELLATION) }
  public static func add(MESSAGE_TYPE: gnssNavMessageType, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MESSAGE_TYPE.rawValue, def: 0, at: VT.MESSAGE_TYPE) }
  public static func add(TIME_SYSTEM: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: TIME_SYSTEM, at: VT.TIME_SYSTEM) }
  public static func add(TOC: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: TOC, at: VT.TOC) }
  public static func add(CLOCK_BIAS: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CLOCK_BIAS, def: 0.0, at: VT.CLOCK_BIAS) }
  public static func add(CLOCK_DRIFT: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CLOCK_DRIFT, def: 0.0, at: VT.CLOCK_DRIFT) }
  public static func add(CLOCK_DRIFT_RATE: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CLOCK_DRIFT_RATE, def: 0.0, at: VT.CLOCK_DRIFT_RATE) }
  public static func add(TRANSMISSION_TIME: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TRANSMISSION_TIME, def: 0.0, at: VT.TRANSMISSION_TIME) }
  public static func add(HEALTH: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: HEALTH, def: 0, at: VT.HEALTH) }
  public static func add(HAS_HEALTH: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: HAS_HEALTH, def: false,
   at: VT.HAS_HEALTH) }
  public static func add(ACCURACY: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ACCURACY, def: 0.0, at: VT.ACCURACY) }
  public static func add(ACCURACY_INDEX: Int32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ACCURACY_INDEX, def: 0, at: VT.ACCURACY_INDEX) }
  public static func add(HAS_ACCURACY_INDEX: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: HAS_ACCURACY_INDEX, def: false,
   at: VT.HAS_ACCURACY_INDEX) }
  public static func addVectorOf(GROUP_DELAYS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: GROUP_DELAYS, at: VT.GROUP_DELAYS) }
  public static func addVectorOf(GROUP_DELAY_NAMES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: GROUP_DELAY_NAMES, at: VT.GROUP_DELAY_NAMES) }
  public static func add(KEPLERIAN: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: KEPLERIAN, at: VT.KEPLERIAN) }
  public static func add(STATE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: STATE, at: VT.STATE) }
  public static func add(DATA_SOURCES: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DATA_SOURCES, def: 0, at: VT.DATA_SOURCES) }
  public static func endGNM(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createGNM(
    _ fbb: inout FlatBufferBuilder,
    SATELLITE_IDOffset SATELLITE_ID: Offset = Offset(),
    CONSTELLATION: gnssConstellation = .gps,
    MESSAGE_TYPE: gnssNavMessageType = .unspecified,
    TIME_SYSTEMOffset TIME_SYSTEM: Offset = Offset(),
    TOCOffset TOC: Offset = Offset(),
    CLOCK_BIAS: Double = 0.0,
    CLOCK_DRIFT: Double = 0.0,
    CLOCK_DRIFT_RATE: Double = 0.0,
    TRANSMISSION_TIME: Double = 0.0,
    HEALTH: UInt32 = 0,
    HAS_HEALTH: Bool = false,
    ACCURACY: Double = 0.0,
    ACCURACY_INDEX: Int32 = 0,
    HAS_ACCURACY_INDEX: Bool = false,
    GROUP_DELAYSVectorOffset GROUP_DELAYS: Offset = Offset(),
    GROUP_DELAY_NAMESVectorOffset GROUP_DELAY_NAMES: Offset = Offset(),
    KEPLERIANOffset KEPLERIAN: Offset = Offset(),
    STATEOffset STATE: Offset = Offset(),
    DATA_SOURCES: UInt32 = 0
  ) -> Offset {
    let __start = GNM.startGNM(&fbb)
    GNM.add(SATELLITE_ID: SATELLITE_ID, &fbb)
    GNM.add(CONSTELLATION: CONSTELLATION, &fbb)
    GNM.add(MESSAGE_TYPE: MESSAGE_TYPE, &fbb)
    GNM.add(TIME_SYSTEM: TIME_SYSTEM, &fbb)
    GNM.add(TOC: TOC, &fbb)
    GNM.add(CLOCK_BIAS: CLOCK_BIAS, &fbb)
    GNM.add(CLOCK_DRIFT: CLOCK_DRIFT, &fbb)
    GNM.add(CLOCK_DRIFT_RATE: CLOCK_DRIFT_RATE, &fbb)
    GNM.add(TRANSMISSION_TIME: TRANSMISSION_TIME, &fbb)
    GNM.add(HEALTH: HEALTH, &fbb)
    GNM.add(HAS_HEALTH: HAS_HEALTH, &fbb)
    GNM.add(ACCURACY: ACCURACY, &fbb)
    GNM.add(ACCURACY_INDEX: ACCURACY_INDEX, &fbb)
    GNM.add(HAS_ACCURACY_INDEX: HAS_ACCURACY_INDEX, &fbb)
    GNM.addVectorOf(GROUP_DELAYS: GROUP_DELAYS, &fbb)
    GNM.addVectorOf(GROUP_DELAY_NAMES: GROUP_DELAY_NAMES, &fbb)
    GNM.add(KEPLERIAN: KEPLERIAN, &fbb)
    GNM.add(STATE: STATE, &fbb)
    GNM.add(DATA_SOURCES: DATA_SOURCES, &fbb)
    return GNM.endGNM(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.SATELLITE_ID, fieldName: "SATELLITE_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CONSTELLATION, fieldName: "CONSTELLATION", required: false, type: gnssConstellation.self)
    try _v.visit(field: VT.MESSAGE_TYPE, fieldName: "MESSAGE_TYPE", required: false, type: gnssNavMessageType.self)
    try _v.visit(field: VT.TIME_SYSTEM, fieldName: "TIME_SYSTEM", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.TOC, fieldName: "TOC", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CLOCK_BIAS, fieldName: "CLOCK_BIAS", required: false, type: Double.self)
    try _v.visit(field: VT.CLOCK_DRIFT, fieldName: "CLOCK_DRIFT", required: false, type: Double.self)
    try _v.visit(field: VT.CLOCK_DRIFT_RATE, fieldName: "CLOCK_DRIFT_RATE", required: false, type: Double.self)
    try _v.visit(field: VT.TRANSMISSION_TIME, fieldName: "TRANSMISSION_TIME", required: false, type: Double.self)
    try _v.visit(field: VT.HEALTH, fieldName: "HEALTH", required: false, type: UInt32.self)
    try _v.visit(field: VT.HAS_HEALTH, fieldName: "HAS_HEALTH", required: false, type: Bool.self)
    try _v.visit(field: VT.ACCURACY, fieldName: "ACCURACY", required: false, type: Double.self)
    try _v.visit(field: VT.ACCURACY_INDEX, fieldName: "ACCURACY_INDEX", required: false, type: Int32.self)
    try _v.visit(field: VT.HAS_ACCURACY_INDEX, fieldName: "HAS_ACCURACY_INDEX", required: false, type: Bool.self)
    try _v.visit(field: VT.GROUP_DELAYS, fieldName: "GROUP_DELAYS", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.GROUP_DELAY_NAMES, fieldName: "GROUP_DELAY_NAMES", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.KEPLERIAN, fieldName: "KEPLERIAN", required: false, type: ForwardOffset<gnssKeplerianBroadcast>.self)
    try _v.visit(field: VT.STATE, fieldName: "STATE", required: false, type: ForwardOffset<gnssStateBroadcast>.self)
    try _v.visit(field: VT.DATA_SOURCES, fieldName: "DATA_SOURCES", required: false, type: UInt32.self)
    _v.finish()
  }
